use ffmpeg_next as ffmpeg;
use ffmpeg::format::context::Output;
use std::path::Path;

pub struct MasterMuxer {
    output_context: Output,
        video_stream_idx: usize,
            audio_stream_idx: usize,
            }

            impl MasterMuxer {
                pub fn initialize(
                        output_path: &str,
                                video_width: i32,
                                        video_height: i32,
                                                audio_codec_id: ffmpeg::codec::Id,
                                                        audio_sample_rate: i32,
                                                                audio_channels: i32,
                                                                    ) -> Result<Self, ffmpeg::Error> {
                                                                            let mut out_ctx = ffmpeg::format::output(&Path::new(output_path))?;

                                                                                    // 1. Configure Video Stream pass-through
                                                                                            let video_codec = ffmpeg::encoder::find(ffmpeg::codec::Id::H264)
                                                                                                        .ok_or(ffmpeg::Error::EncoderNotFound)?;
                                                                                                                let mut v_stream = out_ctx.add_stream(video_codec)?;
                                                                                                                        let v_idx = v_stream.index();

                                                                                                                                unsafe {
                                                                                                                                            let params = (*v_stream.as_mut_ptr()).codecpar;
                                                                                                                                                        (*params).codec_type = ffmpeg::sys::AVMEDIA_TYPE_VIDEO;
                                                                                                                                                                    (*params).codec_id = ffmpeg::sys::AV_CODEC_ID_H264;
                                                                                                                                                                                (*params).width = video_width;
                                                                                                                                                                                            (*params).height = video_height;
                                                                                                                                                                                                    }

                                                                                                                                                                                                            // 2. Configure Audio Stream parameters
                                                                                                                                                                                                                    let audio_codec = ffmpeg::encoder::find(audio_codec_id)
                                                                                                                                                                                                                                .ok_or(ffmpeg::Error::EncoderNotFound)?;
                                                                                                                                                                                                                                        let mut a_stream = out_ctx.add_stream(audio_codec)?;
                                                                                                                                                                                                                                                let a_idx = a_stream.index();

                                                                                                                                                                                                                                                        unsafe {
                                                                                                                                                                                                                                                                    let params = (*a_stream.as_mut_ptr()).codecpar;
                                                                                                                                                                                                                                                                                (*params).codec_type = ffmpeg::sys::AVMEDIA_TYPE_AUDIO;
                                                                                                                                                                                                                                                                                            (*params).codec_id = audio_codec_id.into();
                                                                                                                                                                                                                                                                                                        (*params).sample_rate = audio_sample_rate;
                                                                                                                                                                                                                                                                                                                    (*params).ch_layout.nb_channels = audio_channels;
                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                    out_ctx.write_header()?;

                                                                                                                                                                                                                                                                                                                                            Ok(Self {
                                                                                                                                                                                                                                                                                                                                                        output_context: out_ctx,
                                                                                                                                                                                                                                                                                                                                                                    video_stream_idx: v_idx,
                                                                                                                                                                                                                                                                                                                                                                                audio_stream_idx: a_idx,
                                                                                                                                                                                                                                                                                                                                                                                        })
                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                pub fn write_video_packet(&mut self, payload: &[u8], pts_us: i64, is_keyframe: bool) -> Result<(), ffmpeg::Error> {
                                                                                                                                                                                                                                                                                                                                                                                                        let mut packet = ffmpeg::Packet::copy(payload);
                                                                                                                                                                                                                                                                                                                                                                                                                packet.set_stream(self.video_stream_idx);
                                                                                                                                                                                                                                                                                                                                                                                                                        packet.set_pts(Some(pts_us));
                                                                                                                                                                                                                                                                                                                                                                                                                                packet.set_dts(Some(pts_us));

                                                                                                                                                                                                                                                                                                                                                                                                                                        if is_keyframe {
                                                                                                                                                                                                                                                                                                                                                                                                                                                    packet.set_flags(ffmpeg::packet::Flags::KEY);
                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                    packet.write_interleaved(&mut self.output_context)?;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Ok(())
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    pub fn write_audio_packet(&mut self, packet: &mut ffmpeg::Packet) -> Result<(), ffmpeg::Error> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            packet.set_stream(self.audio_stream_idx);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    packet.write_interleaved(&mut self.output_context)?;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Ok(())
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    pub fn finish(&mut self) -> Result<(), ffmpeg::Error> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            self.output_context.write_trailer()?;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Ok(())
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }